<script setup lang="ts">
// MySqlCustomer List (generated by engineering-platform Generic Module Generator)
// EP UI 2.0 generic list: header + optional stats + search panel + data card.
import { computed, onMounted, reactive, ref } from 'vue';
import { useRouter } from 'vue-router';
import PageHeader from '../../components/PageHeader.vue';
import PageContainer from '../../components/PageContainer.vue';
import SearchForm from '../../components/SearchForm.vue';
import AppTable from '../../components/AppTable.vue';
import StatusTag from '../../components/StatusTag.vue';
import StatCard from '../../components/StatCard.vue';
import ConfirmAction from '../../components/ConfirmAction.vue';
import FormDrawer from '../../components/FormDrawer.vue';
import AppForm from '../../components/AppForm.vue';
import DictionarySelect from '../../components/DictionarySelect.vue';
import PermissionButton from '../../permission/PermissionButton.vue';
import { mySqlCustomerApi } from '../../api/mysql-customer';
import type { MySqlCustomer } from '../../types/mysql-customer';
import { errorMessage, notifySuccess, toastSuccess } from '../../utils/feedback';

const router = useRouter();
const loading = ref(false);
const listError = ref<string | null>(null);
const rows = ref<MySqlCustomer[]>([]);
const total = ref(0);
const page = ref(1);
const size = ref(20);
const filters = reactive({ keyword: '' });

const drawerOpen = ref(false);
const editing = ref<MySqlCustomer | null>(null);
const submitting = ref(false);
const formError = ref<string | null>(null);
const form = reactive({code: '', name: '', phone: '', status: '', level: '' });

const enabledCount = computed(() => rows.value.filter(r => r.status === 'ENABLED').length);
const disabledCount = computed(() => rows.value.length - enabledCount.value);

async function load(): Promise<void> {
  loading.value = true;
  listError.value = null;
  try {
    const result = await mySqlCustomerApi.page({
      page: page.value,
      size: size.value,
      keyword: filters.keyword || undefined,
    });
    rows.value = result.items;
    total.value = result.total;
  } catch (e) { listError.value = errorMessage(e); } finally { loading.value = false; }
}

function resetFilters(): void {
  filters.keyword = '';
  page.value = 1;
  load();
}

function openCreate(): void {
  editing.value = null;
  formError.value = null;
  Object.assign(form, {code: '', name: '', phone: '', status: '', level: '' });
  drawerOpen.value = true;
}

function openEdit(p: MySqlCustomer): void {
  editing.value = p;
  formError.value = null;
  Object.assign(form, {code: p.code, name: p.name, phone: p.phone, status: p.status, level: p.level });
  drawerOpen.value = true;
}

async function submit(): Promise<void> {
  submitting.value = true;
  formError.value = null;
  const body = {code: form.code, name: form.name, phone: form.phone, status: form.status, level: form.level };
  try {
    if (editing.value) { await mySqlCustomerApi.update(editing.value.id, body); notifySuccess('MySqlCustomer updated'); }
    else { await mySqlCustomerApi.create(body); notifySuccess('MySqlCustomer created'); }
    drawerOpen.value = false;
    await load();
  } catch (e) { formError.value = errorMessage(e); } finally { submitting.value = false; }
}

async function doDisable(p: MySqlCustomer): Promise<void> {
  try { await mySqlCustomerApi.disable(p.id); toastSuccess('MySqlCustomer disabled'); await load(); }
  catch (e) { toastSuccess(errorMessage(e)); }
}

onMounted(load);
</script>

<template>
  <PageContainer full-width>
    <PageHeader title="MySqlCustomers" description="Generic business module — mysql-customer." eyebrow="MySqlCustomer">
      <template #actions>
        <PermissionButton permission="demo_customer:item:create" type="primary" data-testid="create-mysql-customer" @click="openCreate">Create MySqlCustomer</PermissionButton>
      </template>
    </PageHeader>

    <div v-if="total > 0" class="list-stats" data-testid="list-stats">
      <StatCard label="Total" :value="total" accent="indigo" marker="T" />
      <StatCard label="Enabled" :value="enabledCount" accent="emerald" marker="E" />
      <StatCard label="Disabled" :value="disabledCount" accent="rose" marker="D" />
    </div>

    <SearchForm more @search="load" @reset="resetFilters">
      <el-input v-model="filters.keyword" placeholder="Search" clearable style="width: 240px" data-testid="mysql-customer-search-keyword" />
    </SearchForm>

    <AppTable :loading="loading" :error="listError" :data="rows" :total="total" :page="page" :size="size" @refresh="load" @update:page="(p: number) => { page = p; load(); }" @update:size="(s: number) => { size = s; page = 1; load(); }">
      <el-table-column prop="code" label="Code" min-width="130" />
      <el-table-column prop="name" label="Name" min-width="130" />
      <el-table-column prop="phone" label="Phone" min-width="130" />
      <el-table-column prop="status" label="Status" min-width="130" />
      <el-table-column prop="level" label="Level" min-width="130" />
      <el-table-column prop="departmentId" label="Department" width="120"><template #default="{ row }">{{ row.departmentId ?? '—' }}</template></el-table-column>
      <el-table-column label="Actions" width="180" fixed="right">
        <template #default="{ row }">
          <el-button size="small" type="primary" link data-testid="mysql-customer-detail-open" @click="router.push({ path: '/mysql-customer/' + row.id })">Detail</el-button>
          <el-button size="small" link data-testid="mysql-customer-open" @click="openEdit(row)">Edit</el-button>
          <ConfirmAction v-if="row.status === 'ENABLED'" :title="'Disable ' + row.id + '?'" @confirm="doDisable(row)">
            <PermissionButton permission="demo_customer:item:disable" size="small" type="danger" link data-testid="mysql-customer-disable-trigger">Disable</PermissionButton>
          </ConfirmAction>
        </template>
      </el-table-column>
    </AppTable>

    <FormDrawer v-model="drawerOpen" :title="editing ? 'Edit MySqlCustomer' : 'Create MySqlCustomer'">
      <AppForm :model="form as unknown as Record<string, unknown>" :submitting="submitting" :error="formError" :submit-text="editing ? 'Save' : 'Create'" compact @submit="submit" @cancel="drawerOpen = false">
        <el-form-item label="Code" :rules="[{ required: true, message: 'Code is required' }]">
          <el-input v-model="form.code" data-testid="mysql-customer-form-code" />
        </el-form-item>
        <el-form-item label="Name" :rules="[{ required: true, message: 'Name is required' }]">
          <el-input v-model="form.name" data-testid="mysql-customer-form-name" />
        </el-form-item>
        <el-form-item label="Phone">
          <el-input v-model="form.phone" data-testid="mysql-customer-form-phone" />
        </el-form-item>
        <el-form-item label="Status" :rules="[{ required: true, message: 'Status is required' }]">
          <el-input v-model="form.status" data-testid="mysql-customer-form-status" />
        </el-form-item>
        <el-form-item label="Level">
          <el-input v-model="form.level" data-testid="mysql-customer-form-level" />
        </el-form-item>
        <div class="form-hint">Department and creator are set by the server from your session — never from the client.</div>
      </AppForm>
    </FormDrawer>
  </PageContainer>
</template>

